// LoadScenarios reads every *.json scenario in dir, sorted by id.
func LoadScenarios(dir string) ([]*Scenario, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*.json"))
	if err != nil {
		return nil, err
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("testkit: no scenarios in %s", dir)
	}
	out := make([]*Scenario, 0, len(files))
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			return nil, err
		}
		var sc Scenario
		if err := json.Unmarshal(data, &sc); err != nil {
			return nil, fmt.Errorf("testkit: %s: %w", f, err)
		}
		if sc.ID == "" || sc.Category == "" {
			return nil, fmt.Errorf("testkit: %s: id and category are required", f)
		}
		sc.File = f
		out = append(out, &sc)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out, nil
}

func (o *Options) selected(sc *Scenario) bool {
	if len(o.Only) > 0 && !contains(o.Only, sc.ID) {
		return false
	}
	if len(o.Categories) == 0 {
		_, ok := o.Factories[sc.Category]
		return ok
	}
	return contains(o.Categories, sc.Category)
}

// RunScenarios runs the selected scenarios in dir and returns a report. It
// returns an error only when the scenarios cannot be loaded.
func RunScenarios(ctx context.Context, dir string, opts Options) (*Report, error) {
	scenarios, err := LoadScenarios(dir)
	if err != nil {
		return nil, err
	}
	rep := &Report{}
	for _, sc := range scenarios {
		if !opts.selected(sc) {
			continue
		}
		rep.add(RunScenario(ctx, sc, opts))
	}
	return rep, nil
}

// Run executes the selected scenarios as subtests of t (one per scenario id).
func Run(t *testing.T, dir string, opts Options) {
	t.Helper()
	scenarios, err := LoadScenarios(dir)
	if err != nil {
		t.Fatalf("load scenarios: %v", err)
	}
	for _, sc := range scenarios {
		if !opts.selected(sc) {
			continue
		}
		t.Run(sc.ID, func(t *testing.T) {
			res := RunScenario(t.Context(), sc, opts)
			for _, s := range res.Steps {
				t.Logf("step %d %s: %s %s", s.Index, s.Op, s.Status, s.Reason)
			}
			switch res.Status {
			case StatusSkipped:
				t.Skip(res.Reason)
			case StatusFailed:
				t.Fatal(res.Reason)
			}
		})
	}
}

// RunScenario executes one scenario.
func RunScenario(ctx context.Context, sc *Scenario, opts Options) (res ScenarioResult) {
	start := time.Now()
	res = ScenarioResult{ID: sc.ID, Category: sc.Category, File: sc.File}
	defer func() { res.Duration = time.Since(start) }()

	if missing := missingCaps(sc.Requires, opts.Capabilities); len(missing) > 0 {
		res.Status, res.Reason = StatusSkipped, "missing capabilities: "+strings.Join(missing, ", ")
		return res
	}
	factory, ok := opts.Factories[sc.Category]
	if !ok || factory == nil {
		res.Status, res.Reason = StatusSkipped, "no factory for category "+sc.Category
		return res
	}
	timeout := opts.ScenarioTimeout
	if timeout <= 0 {
		timeout = 5 * time.Minute
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	env := newEnv(sc, opts)
	defer env.runCleanups()

	target, err := factory(ctx, env)
	if err != nil {
		res.Status, res.Reason = StatusFailed, "factory: "+err.Error()
		return res
	}
	env.Target = target

	res.Status = StatusPassed
	for i, step := range sc.Steps {
		sr := StepResult{Index: i, Op: step.Op}
		if missing := missingCaps(step.Requires, opts.Capabilities); len(missing) > 0 {
			sr.Status, sr.Reason = StatusSkipped, "missing capabilities: "+strings.Join(missing, ", ")
			res.Steps = append(res.Steps, sr)
			continue
		}
		if err := runStep(ctx, env, sc.Category, step); err != nil {
			sr.Status, sr.Reason = StatusFailed, err.Error()
			res.Steps = append(res.Steps, sr)
			res.Status = StatusFailed
			res.Reason = fmt.Sprintf("step %d (%s): %v", i, step.Op, err)
			return res
		}
		sr.Status = StatusPassed
		res.Steps = append(res.Steps, sr)
	}
	return res
}

func newEnv(sc *Scenario, opts Options) *Env {
	run := randomRunID()
	env := &Env{Run: run, Scenario: sc, Vars: map[string]string{"run": run}}
	prefix := opts.Prefix
	if prefix == "" {
		prefix = "grow-conformance/${run}/"
	}
	env.Prefix = env.Expand(prefix)
	env.ServiceName = opts.ServiceName
	if env.ServiceName == "" {
		env.ServiceName = "grow-conformance"
	}
	env.Vars["prefix"] = env.Prefix
	env.Vars["serviceName"] = env.ServiceName
	return env
}

func callHandler(ctx context.Context, h OpHandler, env *Env, args map[string]any) (result, panicked any, err error) {
	defer func() { panicked = recover() }()
	result, err = h(ctx, env, args)
	return result, nil, err
}

func runStep(ctx context.Context, env *Env, category string, step Step) error {
	handler, ok := lookupOp(category, step.Op)
	if !ok {
		return fmt.Errorf("unsupported op %q for category %q", step.Op, category)
	}
	args, _ := env.ExpandValue(step.Args).(map[string]any)
	if args == nil {
		args = map[string]any{}
	}
	if !isPollingOp(category, step.Op) {
		_, err := runOnce(ctx, env, handler, step, args)
		return err
	}
	deadline := time.Now().Add(ArgDuration(args, "timeoutMs", DefaultPollStepTimeout))
	interval := ArgDuration(args, "intervalMs", DefaultPollStepInterval)
	for {
		final, err := runOnce(ctx, env, handler, step, args)
		if err == nil || final || time.Now().Add(interval).After(deadline) {
			return err
		}
		timer := time.NewTimer(interval)
		select {
		case <-ctx.Done():
			timer.Stop()
			return fmt.Errorf("%w (scenario ended while polling)", err)
		case <-timer.C:
		}
	}
}

// runOnce runs the op once and checks its expectations; final reports a failure that
// polling must not repeat (a panic, or an op error that is neither retryable nor
// NOT_FOUND, such as UNSUPPORTED or AUTHENTICATION).
func runOnce(ctx context.Context, env *Env, handler OpHandler, step Step, args map[string]any) (final bool, err error) {
	result, panicErr, opErr := callHandler(ctx, handler, env, args)
	if panicErr != nil {
		return true, fmt.Errorf("op %s panicked: %v", step.Op, panicErr)
	}
	expect, _ := env.ExpandValue(step.Expect).(map[string]any)
	if cerr := checkExpectations(env, expect, result, opErr); cerr != nil {
		var e *zipkin.Error
		transient := errors.As(opErr, &e) && (e.Retryable || e.Code == zipkin.ErrorCodeNotFound)
		return opErr != nil && !transient, cerr
	}
	if step.Save != "" && opErr == nil {
		env.Vars[step.Save] = stringify(result)
	}
	return false, nil
}

func checkExpectations(env *Env, expect map[string]any, result any, opErr error) error {
	if want, ok := expect["error"]; ok {
		if opErr == nil {
			return fmt.Errorf("expected error %v, got success", want)
		}
		var e *zipkin.Error
		if !errors.As(opErr, &e) {
			return fmt.Errorf("expected error %v, got non-SDK error %v", want, opErr)
		}
		if string(e.Code) != fmt.Sprint(want) {
			return fmt.Errorf("expected error %v, got %s (%v)", want, e.Code, opErr)
		}
		return nil
	}
	if opErr != nil {
		return fmt.Errorf("unexpected error: %w", opErr)
	}
	keys := make([]string, 0, len(expect))
	for k := range expect {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		if err := checkOne(env, k, expect[k], result); err != nil {
			return fmt.Errorf("expect %s: %w", k, err)
		}
	}
	return nil
}

func checkOne(env *Env, key string, want, result any) error {
	switch key {
	case "reveal":
		r, ok := result.(interface{ Reveal() (string, error) })
		if !ok || isNil(result) {
			return fmt.Errorf("result %T has no Reveal()", result)
		}
		got, err := r.Reveal()
		if err != nil {
			return err
		}
		if got != fmt.Sprint(want) {
			return errors.New("revealed value differs")
		}
	case "null":
		if truthy(want) != isNil(result) {
			return fmt.Errorf("null=%v but result is %s", want, describe(result))
		}
	case "notNull":
		if truthy(want) == isNil(result) {
			return fmt.Errorf("notNull=%v but result is %s", want, describe(result))
		}
	case "true", "false":
		b, ok := result.(bool)
		if !ok {
			return fmt.Errorf("result %T is not a boolean", result)
		}
		if b != (key == "true") {
			return fmt.Errorf("got %v", b)
		}
	case "equals":
		got := Normalize(result)
		if !subsetEqual(want, got) {
			return fmt.Errorf("got %s, want %s", jsonString(got), jsonString(want))
		}
	case "contains", "notContains":
		has := containsValue(Normalize(result), want)
		if has != (key == "contains") {
			return fmt.Errorf("%s %s in %s failed", key, jsonString(want), jsonString(Normalize(result)))
		}
	case "count", "minCount":
		n, ok := count(result)
		if !ok {
			return fmt.Errorf("result %T has no size", result)
		}
		w := toInt(want)
		if (key == "count" && n != w) || (key == "minCount" && n < w) {
			return fmt.Errorf("got %d, want %s %d", n, key, w)
		}
	case "sorted":
		if truthy(want) && !isSorted(Normalize(result)) {
			return errors.New("result is not sorted by name")
		}
	case "type":
		if got := jsonType(Normalize(result)); got != fmt.Sprint(want) {
			return fmt.Errorf("got type %s, want %v", got, want)
		}
	case "stringForm":
		return checkStringForm(result, want)
	default:
		check, ok := lookupExpectation(key)
		if !ok {
			return fmt.Errorf("unsupported expectation %q", key)
		}
		return check(env, result, want)
	}
	return nil
}

func checkStringForm(result, want any) error {
	m, ok := want.(map[string]any)
	if !ok {
		return errors.New("stringForm needs an object")
	}
	form := StringForm(result)
	if s, ok := m["notContains"]; ok && strings.Contains(form, fmt.Sprint(s)) {
		return errors.New("string form contains a forbidden value")
	}
	if s, ok := m["contains"]; ok && !strings.Contains(form, fmt.Sprint(s)) {
		return fmt.Errorf("string form does not contain %v", s)
	}
	return nil
}

// StringForm returns every printable form of v joined: %v, %+v, %#v, %s and JSON.
func StringForm(v any) string {
	parts := []string{fmt.Sprintf("%v", v), fmt.Sprintf("%+v", v), fmt.Sprintf("%#v", v), fmt.Sprintf("%s", v)}
	if b, err := json.Marshal(v); err == nil {
		parts = append(parts, string(b))
	}
	return strings.Join(parts, "\n")
}

// Normalize converts v to its JSON form (maps, []any, float64, string, bool, nil).
func Normalize(v any) any {
	if isNil(v) {
		return nil
	}
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	var out any
	if err := json.Unmarshal(b, &out); err != nil {
		return fmt.Sprint(v)
	}
	return out
}

// subsetEqual compares want with got; objects in want match when every listed key matches.
func subsetEqual(want, got any) bool {
	switch w := want.(type) {
	case map[string]any:
		g, ok := got.(map[string]any)
		if !ok {
			return false
		}
		for k, wv := range w {
			gv, ok := g[k]
			if !ok || !subsetEqual(wv, gv) {
				return false
			}
		}
		return true
	case []any:
		g, ok := got.([]any)
		if !ok || len(g) != len(w) {
			return false
		}
		for i := range w {
			if !subsetEqual(w[i], g[i]) {
				return false
			}
		}
		return true
	case float64:
		g, ok := got.(float64)
		return ok && g == w
	default:
		return fmt.Sprintf("%T:%v", want, want) == fmt.Sprintf("%T:%v", got, got)
	}
}

func containsValue(got, want any) bool {
	switch g := got.(type) {
	case string:
		return strings.Contains(g, fmt.Sprint(want))
	case []any:
		for _, item := range g {
			if subsetEqual(want, item) {
				return true
			}
		}
	case map[string]any:
		_, ok := g[fmt.Sprint(want)]
		return ok
	}
	return false
}

func count(v any) (int, bool) {
	if c, ok := v.(Counted); ok {
		return c.ConformanceCount(), true
	}
	switch g := Normalize(v).(type) {
	case []any:
		return len(g), true
	case map[string]any:
		return len(g), true
	case string:
		return len(g), true
	case nil:
		return 0, true
	}
	return 0, false
}

func isSorted(v any) bool {
	items, ok := v.([]any)
	if !ok {
		return false
	}
	keys := make([]string, len(items))
	for i, item := range items {
		if m, ok := item.(map[string]any); ok {
			keys[i] = fmt.Sprint(m["name"])
		} else {
			keys[i] = fmt.Sprint(item)
		}
	}
	return sort.StringsAreSorted(keys)
}

func jsonType(v any) string {
	switch v.(type) {
	case string:
		return "string"
	case float64:
		return "number"
	case bool:
		return "boolean"
	case map[string]any:
		return "object"
	case []any:
		return "array"
	default:
		return "null"
	}
}

func isNil(v any) bool {
	if v == nil {
		return true
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Pointer, reflect.Map, reflect.Slice, reflect.Interface, reflect.Func, reflect.Chan:
		return rv.IsNil()
	}
	return false
}

func truthy(v any) bool {
	b, ok := v.(bool)
	return ok && b
}

func toInt(v any) int {
	switch n := v.(type) {
	case float64:
		return int(n)
	case int:
		return n
	}
	return -1
}

func stringify(v any) string {
	switch t := v.(type) {
	case string:
		return t
	case nil:
		return ""
	}
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	return string(b)
}

func describe(v any) string {
	if isNil(v) {
		return "null"
	}
	return fmt.Sprintf("%T", v)
}

func jsonString(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

func missingCaps(required, have []string) []string {
	var missing []string
	for _, r := range required {
		if !contains(have, r) {
			missing = append(missing, r)
		}
	}
	return missing
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

func randomRunID() string {
	const alphabet = "abcdefghijklmnopqrstuvwxyz0123456789"
	var b [8]byte
	_, _ = rand.Read(b[:])
	for i := range b {
		b[i] = alphabet[int(b[i])%len(alphabet)]
	}
	return string(b[:])
}

// ArgString returns args[key] as a string ("" when absent).
func ArgString(args map[string]any, key string) string {
	v, ok := args[key]
	if !ok || v == nil {
		return ""
	}
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprint(v)
}

// ArgInt returns args[key] as an int (def when absent or not a number).
func ArgInt(args map[string]any, key string, def int) int {
	if n, ok := args[key].(float64); ok {
		return int(n)
	}
	return def
}

// ArgBool returns args[key] as a bool (false when absent).
func ArgBool(args map[string]any, key string) bool {
	b, _ := args[key].(bool)
	return b
}

// ArgMap returns args[key] as an object (nil when absent).
func ArgMap(args map[string]any, key string) map[string]any {
	m, _ := args[key].(map[string]any)
	return m
}

// ArgStrings returns args[key] as a string slice (nil when absent).
func ArgStrings(args map[string]any, key string) []string {
	items, _ := args[key].([]any)
	if items == nil {
		return nil
	}
	out := make([]string, 0, len(items))
	for _, it := range items {
		out = append(out, fmt.Sprint(it))
	}
	return out
}

// ArgDuration returns args[key] (milliseconds) as a duration (def when absent).
func ArgDuration(args map[string]any, key string, def time.Duration) time.Duration {
	if n, ok := args[key].(float64); ok {
		return time.Duration(n * float64(time.Millisecond))
	}
	return def
}
